import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    deleteProductDialog: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(delete_product_details, {
          input: {
            product_id: this.rowInfo.product_id,
            product_status: "DEACTIVE"
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.delete_product_details);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
        //
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
